await run('empty-required-body-refusal-and-noop-replacement',async p=>{await fill(p,'次のことを2回くり返す。\n  点数に1を足す。');await block(p);let child=p.locator('#blockEditor .blockui-node[data-schema-id="NumericUpdate:ADD"]');const before=await state(p);await openNodeMenu(child);await child.locator('[data-blockui-action="remove"]').first().click();assert.deepEqual(await state(p),before);await openNodeMenu(child);await (await reveal(child.locator('[data-blockui-action="replace-noop"]'))).click();assert.match((await state(p)).source,/何もしない/);assert.equal((await state(p)).history,before.history+1);await (await reveal(p.locator('#undoBtn'))).click();assert.equal((await state(p)).source,before.source);return{emptyBodyRejectedAtomically:true,explicitNoOpReplacementUndo:true};});
await run('unknown-callee-and-all-arguments-after-definition-change',async p=>{await (await reveal(p.locator('#procBtn'))).click();await (await reveal(p.locator('#callableNewFunction'))).click();await (await reveal(p.locator('#callableName'))).fill('二倍');await (await reveal(p.locator('#callableArgs'))).fill('元値');await (await reveal(p.locator('#callableCode'))).fill('元値×2を返す。');await (await reveal(p.locator('#callableSave'))).click();await (await reveal(p.locator('#procClose'))).click();await fill(p,'二倍（1）と言う。');await block(p);const original=(await state(p)).source;await (await reveal(p.locator('#procBtn'))).click();await (await reveal(p.locator('#callableName'))).fill('改名');await (await reveal(p.locator('#callableArgs'))).fill('元値、追加');await (await reveal(p.locator('#callableSave'))).click();await (await reveal(p.locator('#procClose'))).click();assert.equal((await state(p)).source,original);assert.equal(await p.locator('#blockEditor .blockui-node[data-schema-id="UserFunctionCall"] [data-blockui-field="name"]').inputValue(),'二倍');assert.ok(await p.locator('#blockEditor .blockui-diagnostics').count());assert.equal((await tree(p)).bodies.body[0].inputs.value.inputs.args.length,1);await (await reveal(p.locator('#undoBtn'))).click();assert.equal((await state(p)).source,original);return{callerNotRenamedOrReArityAdjusted:true,diagnosticsRefresh:true};});
await run('source-each-limit-refusal-keeps-source-history',async p=>{await fill(p,'点数を1にする。');const source='「'+'a'.repeat(99995)+'」と言う';assert.equal([...source].length,100000);await fill(p,source);const before=await state(p);assert.equal(before.source.length,100000);await (async()=>{const control=await reveal(p.locator('#formatBtn')); await openBodyForTest(control.page()); return control.click();})();assert.deepEqual(await state(p),before);assert.equal(await p.locator('#codeEditor').inputValue(),source);await block(p);const original=await state(p);await (async()=>{const control=await reveal(p.locator('#blockEditor .blockui-node[data-schema-id="StringLiteral"] [data-blockui-field="value"]')); await openBodyForTest(control.page()); return control.fill('a'.repeat(99996));})();await (async()=>{const control=await reveal(p.locator('#blockEditor [data-blockui-action="commit"]')); await openBodyForTest(control.page()); return control.click();})();assert.deepEqual(await state(p),original);return{maxCodePreserved:true,formatExpansionRejected:true,guiExpansionRejectedAtomically:true};});

