await run('activeTasks',async p=>{const project=base(),model=JSON.parse(JSON.stringify(project.components[0]));project.components=Array.from({length:499},(_,i)=>({...model,id:'target-'+i,name:'対象'+i,x:0,y:0,localData:{variables:[],lists:[]}}));project.scripts=[{targetId:'stage',event:'start',source:'次のことを4回くり返す。
  「全員」と知らせる。'},...['stage',...project.components.map(x=>x.id)].map(targetId=>({targetId,event:'message',source:'100秒待つ。'}))];await open(p,project,'activeTasks-boundary');await p.evaluate(()=>{window.__taskProof=[];const original=Akari.EventScheduler.prototype.createTask;Akari.EventScheduler.prototype.createTask=function(...args){try{const result=original.apply(this,args);if(this.tasks.size>=1999)__taskProof.push({size:this.tasks.size,created:!!result});return result;}catch(error){__taskProof.push({size:this.tasks.size,error:error.code});throw error;}};});const before=await state(p);await (await reveal(p.locator('#runBtn'))).click();await p.locator('#failureModal.show').waitFor();assert.match(await p.locator('#failureBody').textContent(),/R413/);const proof=await p.evaluate(()=>__taskProof);assert.ok(proof.some(x=>x.size===1999&&x.created));assert.ok(proof.some(x=>x.size===2000&&x.created));assert.ok(proof.some(x=>x.size===2000&&x.error==='R413'));await (await reveal(p.locator('#failureClose'))).click();await (await reveal(p.locator('#stopBtn'))).click();assert.deepEqual(await state(p),before);return{proof,observer:'Transparent wrapper records original createTask results without changing limits/tasks/results'};});
await run('blockDepth',async p=>{const out=[];for(const n of [127,128]){const source=Array.from({length:n},(_,i)=>'  '.repeat(i)+'次のことを1回くり返す。').concat('  '.repeat(n)+'何もしない。').join('
');await (async()=>{const control=await reveal(p.locator('#editorModecode')); await openBodyForTest(control.page()); return control.click();})();await (async()=>{const control=await reveal(p.locator('#codeEditor')); await openBodyForTest(control.page()); return control.fill(source);})();await p.waitForTimeout(350);await (async()=>{const control=await reveal(p.locator('#editorModeblocks')); await openBodyForTest(control.page()); return control.click();})();assert.equal(await p.locator('#blockEditor .blockui-node[data-schema-id="RepeatCount"]').count(),n);out.push({depth:n,blocksRendered:n});}const before=await state(p),deepest=await p.evaluate(()=>{let node=Akari.app.editorState.main.blockView.bodies.body[0];while(node.bodies?.body?.[0]?.schemaId==='RepeatCount')node=node.bodies.body[0];return node.id;});await (async()=>{const control=p.locator('#blockEditor [data-blockui-body="body"][data-parent-id="'+deepest+'"]').last(); await openBodyForTest(control.page()); return control.click();})();await showUnavailable(p.locator('#blockEditor'));await (async()=>{const control=await reveal(p.locator('#blockEditor [data-blockui-search]')); await openBodyForTest(control.page()); return control.fill('Forever');})();const choice=p.locator('#blockEditor [data-blockui-schema="Forever"]');const reason=await inspectUnavailableChoice(choice,()=>state(p));assert.deepEqual(await state(p),before);return{cases:out,guiOverDepthRejected:true,reason,unavailableClickPreservedSourceAndHistory:true};});
